<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,School,SitePresentation};
use App\Services\SitePresentationService;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
class AdminWorkspaceTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void{if(getenv('RUTEAMAN_SPATIAL_TESTS')!=='1')$this->markTestSkipped('Dedicated spatial database required.');parent::setUp();$this->seed(\Database\Seeders\DemoSeeder::class);Storage::fake('local');}
 private function owner(bool $reauth=true):User{$u=(new User)->forceFill(['display_name'=>'Owner Workspace','email'=>'workspace-owner@test.invalid','password'=>'FixturePassword123!','active'=>true,'status'=>'active','role'=>'owner','permissions'=>[]]);$u->save();$this->actingAs($u);$this->withSession(['admin.reauth_at'=>$reauth?time():0,'admin.last_seen'=>time()]);return $u;}
 private function school():School{return School::where('name','Sekolah A — Demo Simulasi')->firstOrFail();}
 private function admin():User{$u=User::where('email','admin_a@ruteaman.test')->firstOrFail();$u->forceFill(['permissions'=>['schools.view','schools.manage']])->save();$this->actingAs($u)->withSession(['admin.reauth_at'=>time(),'admin.last_seen'=>time()]);return $u;}
 private function upload(){return $this->post(route('admin.presentation.photo'),['photo'=>UploadedFile::fake()->image('login.jpg',1000,700),'alt'=>'Ilustrasi sekolah','publication_consent'=>1]);}
 public function test_guest_and_school_admin_cannot_manage_global_presentation():void{$this->get('/admin/presentation')->assertRedirect(route('login'));$this->admin();$this->get('/admin/presentation')->assertForbidden();$this->post(route('admin.presentation.photo'),['photo'=>'bad'])->assertForbidden();$this->owner(false);$this->get('/admin/presentation')->assertOk();$this->patchJson(route('admin.presentation.contact'),['help_contact'=>'0211234','publication_consent'=>1])->assertStatus(428);}
 public function test_login_photo_reencoded_public_versioned_and_reset():void{$this->owner();$this->upload()->assertRedirect(route('admin.presentation'));$s=SitePresentation::findOrFail(1);$this->assertTrue(Storage::disk('local')->exists($s->login_photo_path));$this->assertSame('image/webp',getimagesize(Storage::disk('local')->path($s->login_photo_path))['mime']);$this->assertArrayNotHasKey('login_photo_path',$s->toArray());$url=app(SitePresentationService::class)->loginPhoto()['url'];$this->get($url)->assertOk()->assertHeader('Cache-Control','no-store, private');$old=$s->login_photo_path;$this->upload()->assertRedirect();$this->assertFalse(Storage::disk('local')->exists($old));$this->assertNotSame($url,app(SitePresentationService::class)->loginPhoto()['url']);$new=$s->fresh()->login_photo_path;$this->delete(route('admin.presentation.reset'))->assertRedirect();$this->assertFalse(Storage::disk('local')->exists($new));$this->get(route('site.login-photo'))->assertNotFound();$this->assertStringContainsString('/images/siswa-berangkat-ke-sekolah.webp',app(SitePresentationService::class)->loginPhoto()['url']);}
 public function test_invalid_photo_and_missing_publication_consent_rejected():void{$this->owner();$this->post(route('admin.presentation.photo'),['photo'=>UploadedFile::fake()->create('bad.svg',2,'image/svg+xml'),'alt'=>'Bad','publication_consent'=>1])->assertSessionHasErrors('photo');$this->post(route('admin.presentation.photo'),['photo'=>UploadedFile::fake()->image('ok.png'),'alt'=>'Example'])->assertSessionHasErrors('publication_consent');$this->assertNull(SitePresentation::find(1)->login_photo_path);}
 public function test_platform_contact_and_school_override_preserve_other_settings():void{$this->owner();$this->patch(route('admin.presentation.contact'),['help_contact'=>'https://school.example/help','publication_consent'=>1])->assertRedirect();$s=$this->school();$s->update(['settings'=>['existing_setting'=>true]]);$this->patch(route('admin.school-contacts.update',$s),['help_contact'=>'mailto:office@school.example','publication_consent'=>1])->assertRedirect();$this->assertSame('mailto:office@school.example',app(SitePresentationService::class)->contact($s->fresh()));$this->assertTrue($s->fresh()->settings['existing_setting']);$this->assertSame('https://school.example/help',app(SitePresentationService::class)->contact());$this->patch(route('admin.school-contacts.update',$s),['help_contact'=>'','publication_consent'=>1])->assertRedirect();$this->assertSame('https://school.example/help',app(SitePresentationService::class)->contact($s->fresh()));}
 public function test_contact_rejects_unsafe_links_and_requires_publication_consent():void{$this->owner();foreach(['javascript:alert(1)','http://insecure.example','mailto:not-an-email','<script>x</script>'] as $contact)$this->patch(route('admin.presentation.contact'),['help_contact'=>$contact,'publication_consent'=>1])->assertSessionHasErrors('help_contact');$this->patch(route('admin.presentation.contact'),['help_contact'=>'0211234'])->assertSessionHasErrors('publication_consent');$this->assertNull(SitePresentation::find(1)->help_contact);}
 public function test_school_contacts_scope_and_write_permissions_enforced():void{$u=$this->admin();$this->get('/admin/school-contacts')->assertOk()->assertSee($u->school->name)->assertDontSee('Sekolah B — Demo Simulasi');$other=School::whereKeyNot($u->school_id)->firstOrFail();$this->patch(route('admin.school-contacts.update',$other),['help_contact'=>'0211234','publication_consent'=>1])->assertForbidden();$this->patch(route('admin.school-contacts.update',$u->school),['help_contact'=>'0211234','publication_consent'=>1])->assertRedirect();$u->forceFill(['permissions'=>['schools.view']])->save();$this->patch(route('admin.school-contacts.update',$u->school),['help_contact'=>'new','publication_consent'=>1])->assertForbidden();}
 public function test_all_admin_account_tabs_keep_sidebar_and_roles():void{$this->owner();foreach(['profile','settings','notifications','security','privacy'] as $section){$this->get('/admin/account/'.$section)->assertOk()->assertSee('id="admin-sidebar"',false)->assertDontSee('class="mobile-tabs-root"',false);$this->get('/account/'.$section)->assertOk()->assertSee('id="admin-sidebar"',false);}$this->get('/admin/account/profile')->assertSee('Admin Utama')->assertSee('Panduan Administrator')->assertSee(route('admin.account.settings'),false);}
 public function test_student_account_stays_separate_and_cannot_enter_admin_pages():void{$u=User::where('email','siswa_1@ruteaman.test')->firstOrFail();$this->actingAs($u);$this->get('/account/profile')->assertOk()->assertDontSee('id="admin-sidebar"',false)->assertSee('Panduan Pengguna');foreach(['/admin/account/profile','/admin/guide','/admin/school-contacts'] as $uri)$this->get($uri)->assertForbidden();}
 public function test_admin_guide_scoped_owner_chapters_and_school_admin_chapters():void{$this->owner();$this->get('/admin/guide')->assertOk()->assertSee('id="foto-masuk"',false)->assertSee('id="jenis-kondisi"',false)->assertSee('id="kontak"',false);$this->admin();$this->get('/admin/guide')->assertOk()->assertDontSee('id="foto-masuk"',false)->assertDontSee('id="jenis-kondisi"',false)->assertSee('id="kontak"',false);}
}
